</pre></blockquote>
</html>"));
end reverse;

function sort "Sort elements of complex vector"
  extends Modelica.Icons.Function;
  input Complex v[:] "Vector to be sorted";
  input Boolean ascending = true
        "= true if ascending order, otherwise descending order";
  input Boolean sortFrequency=true
        "= true, if sorting is first for imaginary then for real value; = false, if sorting is for absolute value";
  output Complex sorted_v[size(v,1)] = v "Sorted vector";
  output Integer indices[size(v,1)] = 1:size(v,1) "sorted_v = v[indices]";

  /* shellsort algorithm; should be improved later */
    protected
  Integer gap;
  Integer i;
  Integer j;
  Complex wv;
  Integer wi;
  Integer nv = size(v,1);
  Boolean swap;
  Integer k1;
  Integer k2;
algorithm
  gap := div(nv,2);

  while gap > 0 loop
     i := gap;
     while i < nv loop
        j := i-gap;
        if j>=0 then
           k1 := j+1;
           k2 := j + gap + 1;
           if sortFrequency then
              if ascending then
                 swap := .abs(sorted_v[k1].im) >  .abs(sorted_v[k2].im) or
                         .abs(sorted_v[k1].im) == .abs(sorted_v[k2].im) and
                         (sorted_v[k1].re  > sorted_v[k2].re or
                          sorted_v[k1].re  == sorted_v[k2].re and sorted_v[k1].im < sorted_v[k2].im);
              else
                 swap := .abs(sorted_v[k1].im) <  .abs(sorted_v[k2].im) or
                         .abs(sorted_v[k1].im) == .abs(sorted_v[k2].im) and
                         (sorted_v[k1].re  < sorted_v[k2].re or
                          sorted_v[k1].re  == sorted_v[k2].re and sorted_v[k1].im < sorted_v[k2].im);
              end if;
           else
              if ascending then
                 swap := ComplexMath.abs(sorted_v[k1]) > ComplexMath.abs(sorted_v[k2]);
              else
                 swap := ComplexMath.abs(sorted_v[k1]) < ComplexMath.abs(sorted_v[k2]);
              end if;
           end if;
        else
           swap := false;
        end if;

        while swap loop
           wv := sorted_v[j+1];
           wi := indices[j+1];
           sorted_v[j+1] := sorted_v[j+gap+1];
           sorted_v[j+gap+1] := wv;
           indices[j+1] := indices[j+gap+1];
           indices[j+gap+1] := wi;
           j := j - gap;
           if j >= 0 then
              k1 := j+1;
              k2 := j + gap + 1;
              if sortFrequency then
                 if ascending then
                    swap := .abs(sorted_v[k1].im) >  .abs(sorted_v[k2].im) or
                            .abs(sorted_v[k1].im) == .abs(sorted_v[k2].im) and
                            (sorted_v[k1].re  > sorted_v[k2].re or
                             sorted_v[k1].re  == sorted_v[k2].re and sorted_v[k1].im < sorted_v[k2].im);
                 else
                    swap := .abs(sorted_v[k1].im) <  .abs(sorted_v[k2].im) or
                            .abs(sorted_v[k1].im) == .abs(sorted_v[k2].im) and
                            (sorted_v[k1].re  < sorted_v[k2].re or
                             sorted_v[k1].re  == sorted_v[k2].re and sorted_v[k1].im < sorted_v[k2].im);
                 end if;
              else
                 if ascending then
                    swap := ComplexMath.abs(sorted_v[k1]) > ComplexMath.abs(sorted_v[k2]);
                 else
                    swap := ComplexMath.abs(sorted_v[k1]) < ComplexMath.abs(sorted_v[k2]);
                 end if;
              end if;
           else
              swap := false;
           end if;
        end while;
        i := i + 1;
     end while;
     gap := div(gap,2);
  end while;

  annotation (Documentation(info="<html>
<h4>Syntax</h4>
<blockquote><pre>
           sorted_v = Vectors.<strong>sort</strong>(v);
(sorted_v, indices) = Vectors.<strong>sort</strong>(v, ascending=true);
</pre></blockquote>

<h4>Description</h4>
<p>
Function <strong>sort</strong>(..) sorts a Real vector v
in ascending order and returns the result in sorted_v.
If the optional argument \"ascending\" is <strong>false</strong>, the vector
is sorted in descending order. In the optional second
output argument the indices of the sorted vector with respect
to the original vector are given, such that sorted_v = v[indices].
</p>

<h4>Example</h4>
<blockquote><pre>
(v2, i2) := Vectors.sort({-1, 8, 3, 6, 2});
    -> v2 = {-1, 2, 3, 6, 8}
       i2 = {1, 5, 3, 4, 2}
</pre></blockquote>

</html>"));
end sort;

  annotation(Documentation(info="<html>
<p>
This library provides functions operating on vectors
of Complex numbers.
</p>
</html>"));
end Vectors;

  function sin "Sine of complex number"
    extends Modelica.Icons.Function;
    input Complex c1 "Complex number";
    output Complex c2 "sin(c1)";
  algorithm
     c2 := (exp(Complex(-c1.im, +c1.re)) - exp(Complex(+c1.im, -c1.re)))/Complex(0, 2);
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the Complex sine of the Complex input.</p>
</html>"));
  end sin;

  function cos "Cosine of complex number"
    extends Modelica.Icons.Function;
    input Complex c1 "Complex number";
    output Complex c2 "= cos(c1)";
  algorithm
    c2 := (exp(Complex(-c1.im, +c1.re)) + exp(Complex(+c1.im, -c1.re)))/2;
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the Complex cosine of the Complex input.</p>
</html>"));
  end cos;

  function tan "Tangent of complex number"
    extends Modelica.Icons.Function;
    input Complex c1 "Complex number";
    output Complex c2 "= tan(c1)";
  algorithm
    c2 := sin(c1)/cos(c1);
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the Complex tangent of the Complex input.</p>
</html>"));
  end tan;

  function asin "Arc-sine of complex number"
    extends Modelica.Icons.Function;
    input Complex c1 "Complex number";
    output Complex c2 "arc_sin(c1)";
  algorithm
    c2 := -j*log(j*c1 + sqrt(1 - c1*c1));
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the inverse Complex sine of the Complex input.</p>
</html>"));
  end asin;

  function acos "Arc-cosine of complex number"
    extends Modelica.Icons.Function;
    input Complex c1 "Complex number";
    output Complex c2 "= arc_cos(c1)";
  algorithm
    c2 := -j*log(c1 + j*sqrt(1 - c1*c1));
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the inverse Complex cosine of the Complex input.</p>
</html>"));
  end acos;

  function atan "Arc-tangent of complex number"
    extends Modelica.Icons.Function;
    input Complex c1 "Complex number";
    output Complex c2 "= arc_tan(c1)";
  algorithm
    c2 := 0.5*j*log((j + c1)/(j - c1));
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the inverse Complex tangent of the Complex input.</p>
</html>"));
  end atan;

  function sinh "Hyperbolic-sine of complex number"
    extends Modelica.Icons.Function;
    input Complex c1 "Complex number";
    output Complex c2 "sinh(c1)";
  algorithm
    c2 := Complex(Math.sinh(c1.re)*Math.cos(c1.im), Math.cosh(c1.re)*Math.sin(c1.im));
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the Complex hyperbolic sine of the Complex input.</p>
</html>"));
  end sinh;

  function cosh "Hyperbolic-cosine of complex number"
    extends Modelica.Icons.Function;
    input Complex c1 "Complex number";
    output Complex c2 "= cosh(c1)";
  algorithm
    c2 := Complex(Math.cosh(c1.re)*Math.cos(c1.im), Math.sinh(c1.re)*Math.sin(c1.im));
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the Complex hyperbolic cosine of the Complex input.</p>
</html>"));
  end cosh;

  function tanh "Hyperbolic-tangent of complex number"
    extends Modelica.Icons.Function;
    input Complex c1 "Complex number";
    output Complex c2 "= tanh(c1)";
  algorithm
    c2 := sinh(c1)/cosh(c1);
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the Complex hyperbolic tangent of the Complex input.</p>
</html>"));
  end tanh;

  function asinh "Area-hyperbolic-sine of complex number"
    extends Modelica.Icons.Function;
    input Complex c1 "Complex number";
    output Complex c2 "ar_sinh(c1)";
  algorithm
    c2 := log(c1 + sqrt(c1*c1 + 1));
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the inverse Complex hyperbolic sine of the Complex input.</p>
</html>"));
  end asinh;

  function acosh "Area-hyperbolic-cosine of complex number"
    extends Modelica.Icons.Function;
    input Complex c1 "Complex number";
    output Complex c2 "= ar_cosh(c1)";
  algorithm
    c2 := log(c1 + (c1 + 1)*sqrt((c1 - 1)/(c1 + 1)));
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the inverse Complex hyperbolic cosine of the Complex input.</p>
</html>"));
  end acosh;

  function atanh "Area-hyperbolic-tangent of complex number"
    extends Modelica.Icons.Function;
    input Complex c1 "Complex number";
    output Complex c2 "= ar_tanh(c1)";
  algorithm
    c2 := 0.5*log((1 + c1)/(1 - c1));
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the inverse Complex hyperbolic tangent of the Complex input.</p>
</html>"));
  end atanh;

  function exp "Exponential of complex number"
    extends Modelica.Icons.Function;
    input Complex c1 "Complex number";
    output Complex c2 "= exp(c1)";
  algorithm
    c2 := Complex(Math.exp(c1.re)*Math.cos(c1.im), Math.exp(c1.re)*Math.sin(c1.im));
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the Complex natural exponential of the Complex input.</p>
</html>"));
  end exp;

  function log "Logarithm of complex number"
    extends Modelica.Icons.Function;
    input Complex c1 "Complex number";
    output Complex c2 "= log(c1)";
  algorithm
    c2 := Complex(Modelica.Math.log(abs(c1)), arg(c1));
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the Complex natural logarithm of the Complex input.</p>
</html>"));
  end log;

  function abs "Absolute value of complex number"
    extends Modelica.Icons.Function;
    input Complex c "Complex number";
    output Real result "= abs(c)";
  algorithm
    result := .sqrt(c.re^2 + c.im^2); // Real, not complex sqrt
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the Real absolute of the Complex input, i.e., its length.</p>
</html>"));
  end abs;

  function arg "Phase angle of complex number"
    extends Modelica.Icons.Function;
    input Complex c "Complex number";
    input Modelica.Units.SI.Angle phi0=0
      "Phase angle phi shall be in the range: -pi < phi-phi0 < pi";
    output Modelica.Units.SI.Angle phi "= phase angle of c";
  algorithm
    phi := Modelica.Math.atan3(
        c.im,
        c.re,
        phi0);
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the Real argument of the Complex input, i.e., its angle.</p>
</html>"));
  end arg;

  function conj "Conjugate of complex number"
    extends Modelica.Icons.Function;
    input Complex c1 "Complex number";
    output Complex c2 "= c1.re - j*c1.im";
  algorithm
    c2 := Complex(c1.re, -c1.im);
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the Complex conjugate of the Complex input.</p>
</html>"));
  end conj;

  function real "Real part of complex number"
    extends Modelica.Icons.Function;
    input Complex c "Complex number";
    output Real r "= c.re";
  algorithm
    r := c.re;
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the real part of the Complex input.</p>
</html>"));
  end real;

  function imag "Imaginary part of complex number"
    extends Modelica.Icons.Function;
    input Complex c "Complex number";
    output Real r "= c.im";
  algorithm
    r := c.im;
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the imaginary part of the Complex input.</p>
</html>"));
  end imag;

  function fromPolar "Complex from polar representation"
    extends Modelica.Icons.Function;
    input Real len "abs of complex";
    input Modelica.Units.SI.Angle phi "arg of complex";
    output Complex c "= len*cos(phi) + j*len*sin(phi)";
  algorithm
    c := Complex(len*Modelica.Math.cos(phi), len*Modelica.Math.sin(phi));
    annotation(Inline=true, Documentation(info="<html>
<p>This function constructs a Complex number from its length (absolute) and angle (argument).</p>
</html>"));
  end fromPolar;

  function sqrt "Square root of complex number"
    extends Modelica.Icons.Function;
    input Complex c1 "Complex number";
    output Complex c2 "= sqrt(c1)";
  algorithm
    c2 := Complex(.sqrt(abs(c1))*Math.cos(arg(c1)/2), .sqrt(abs(c1))*Math.sin(arg(c1)/2));
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the Complex square root (principal square root) of the Complex input.</p>
</html>"));
  end sqrt;

  function max "Return maximum element of complex vector"
    extends Modelica.Icons.Function;
    input Complex v[:] "Vector";
    output Complex result "Element of v with largest absolute value";
    output Integer index "v[index] has the largest absolute value";
  protected
    Real absv_i;
    Real absres;
  algorithm
    if size(v,1) > 0 then
      absres := abs(v[1]);
      index  := 1;
      for i in 2:size(v,1) loop
        absv_i := abs(v[i]);
        if absv_i > absres then
          absres := absv_i;
          index := i;
        end if;
      end for;
      result :=v[index];
    else
      result := Complex(0);
      index  := 0;
    end if;
    annotation(Documentation(info="<html>
<p>This function returns the largest element of the Complex input vector, defined by the Complex absolute.</p>
</html>"));
  end max;

  function min "Return minimum element of complex vector"
    extends Modelica.Icons.Function;
    input Complex v[:] "Vector";
    output Complex result "Element of v with smallest absolute value";
    output Integer index "v[index] has the smallest absolute value";
  protected
    Real absv_i;
    Real absres;
  algorithm
    if size(v,1) > 0 then
      absres := abs(v[1]);
      index  := 1;
      for i in 2:size(v,1) loop
        absv_i := abs(v[i]);
        if absv_i < absres then
          absres := absv_i;
          index := i;
        end if;
      end for;
      result :=v[index];
    else
      result := Complex(0);
      index  := 0;
    end if;
    annotation(Documentation(info="<html>
<p>This function returns the smallest element of the Complex input vector, defined by the Complex absolute.</p>
</html>"));
  end min;

  function sum "Return sum of complex vector"
    extends Modelica.Icons.Function;
    input Complex v[:] "Vector";
    output Complex result "Complex sum of vector elements";
  algorithm
    result:=Complex(.sum(v[:].re), .sum(v[:].im));
    annotation(Inline=true, Documentation(info="<html>
<p>This function returns the Complex sum of the Complex input vector</p>
</html>"));
  end sum;

  function product "Return product of complex vector"
    extends Modelica.Icons.Function;
    input Complex v[:] "Vector";
    output Complex result "Complex product of vector elements";
  algorithm
    result:=Complex(1);
    for i in 1:size(v,1) loop
      result:=result * v[i];
    end for;
    annotation(Documentation(info="<html>
<p>This function returns the Complex product of the Complex input vector</p>
</html>"));
  end product;

  annotation (Documentation(info="<html>
<p>
This package contains <strong>basic mathematical functions</strong>
operating on complex numbers (such as sin(..)),
as well as functions operating on vectors of complex numbers.
</p>

</html>"), Icon(coordinateSystem(extent={{-100,-100},{100,100}},
          preserveAspectRatio=false), graphics={
        Line(points={{32,-86},{32,88}}, color={175,175,175}),
        Line(points={{-84,2},{88,2}}, color={175,175,175}),
        Line(
          points={{-50,75},{-5,30}}),
        Line(
          points={{-50,30},{-5,75}}),
        Line(
          points={{-50,-30},{-5,-75}}),
        Line(
          points={{-50,-75},{-5,-30}})}));

end ComplexMath;

within Modelica.Electrical.Analog.Basic;
model OpAmp "Simple nonideal model of an OpAmp with limitation"
  parameter Real Slope(start=10000)
    "Slope of the out.v/vin characteristic at vin=0";
  Modelica.Electrical.Analog.Interfaces.PositivePin in_p
    "Positive pin of the input port" annotation (Placement(transformation(
          extent={{-110,-70},{-90,-50}}), iconTransformation(extent={{-110,-70},{-90,-50}})));
  Modelica.Electrical.Analog.Interfaces.NegativePin in_n
    "Negative pin of the input port" annotation (Placement(transformation(
          extent={{-90,50},{-110,70}}), iconTransformation(extent={{-90,50},{-110,70}})));
  Modelica.Electrical.Analog.Interfaces.PositivePin out "Output pin"
    annotation (Placement(transformation(extent={{110,-10},{90,10}}), iconTransformation(extent={{110,-10},{90,10}})));
  Modelica.Electrical.Analog.Interfaces.PositivePin VMax
    "Positive output voltage limitation" annotation (Placement(transformation(
          extent={{-10,90},{10,110}}), iconTransformation(extent={{-10,90},{10,110}})));
  Modelica.Electrical.Analog.Interfaces.NegativePin VMin
    "Negative output voltage limitation" annotation (Placement(transformation(
          extent={{-10,-110},{10,-90}}), iconTransformation(extent={{-10,-110},{10,-90}})));
  SI.Voltage vin "Input voltage";
protected
  Real f "Auxiliary variable";
  Real absSlope;
equation
  in_p.i = 0;
  in_n.i = 0;
  VMax.i = 0;
  VMin.i = 0;
  vin = in_p.v - in_n.v;
  f = 2/(VMax.v - VMin.v);
  absSlope = if (Slope < 0) then -Slope else Slope;
  out.v = (VMax.v + VMin.v)/2 + absSlope*vin/(1 + absSlope*smooth(0, (if (f*
    vin < 0) then -f*vin else f*vin)));
  annotation (
    Documentation(info="<html>
<p>The OpAmp is a simple nonideal model with a smooth out.v = f(vin) characteristic, where &quot;vin = in_p.v - in_n.v&quot;. The characteristic is limited by VMax.v and VMin.v. Its slope at vin=0 is the parameter Slope, which must be positive. (Therefore, the absolute value of Slope is taken into calculation.)</p>
</html>",
        revisions="<html>
<ul>
<li><em> 2000   </em>
       by Christoph Clauss<br> initially implemented<br>
       </li>
</ul>
</html>"),
    Icon(coordinateSystem(preserveAspectRatio=true, extent={{-100,-100},{100,
            100}}), graphics={
        Polygon(
          points={{70,0},{-70,80},{-70,-80},{70,0}},
          fillColor={255,255,255},
          fillPattern=FillPattern.Solid,
          lineColor={0,0,255}),
        Line(points={{-45,-10},{-20,-10},{-14,-9},{-11,-7},{-9,7},{-6,9},{0,
              10},{20,10}}, color={0,0,255}),
        Line(points={{0,40},{0,100}}, color={0,0,255}),
        Line(points={{0,-40},{0,-100}}, color={0,0,255}),
        Line(points={{-100,60},{-70,60}}, color={0,0,255}),
        Line(points={{-100,-60},{-70,-60}}, color={0,0,255}),
        Line(points={{70,0},{100,0}}, color={0,0,255}),
        Line(points={{-58,50},{-38,50}}, color={0,0,255}),
        Line(points={{-49,-40},{-49,-61}}, color={0,0,255}),
        Line(points={{-60,-51},{-38,-51}}, color={0,0,255}),
        Text(
          extent={{-150,150},{150,110}},
          textString="%name",
          textColor={0,0,255})}));
end OpAmp;

within Modelica.Electrical.Analog.Basic;
model OpAmpDetailed "Detailed model of an operational amplifier"
  // literature: Conelly, J.A.; Choi, P.: Macromodelling with SPICE. Englewood Cliffs: Prentice-Hall, 1992
  import Modelica.Constants.pi;
  parameter SI.Resistance Rdm=2.0e6
    "Input resistance (differential input mode)";
  parameter SI.Resistance Rcm=2.0e9 "Input resistance (common mode)";
  parameter SI.Capacitance Cin=1.4e-12 "Input capacitance";
  parameter SI.Voltage Vos=1.0e-3 "Input offset voltage";
  parameter SI.Current Ib=80.0e-9 "Input bias current";
  parameter SI.Current Ios=20.0e-9 "Input offset current";
  parameter SI.Voltage vcp=0.0 "Correction value for limiting by p_supply";
  parameter SI.Voltage vcm=0.0 "Correction value for limiting by msupply";
  parameter Real Avd0=106.0 "Differential amplifier [dB]";
  parameter Real CMRR=90.0 "Common-mode rejection [dB]";
  parameter SI.Frequency fp1=5.0 "Dominant pole";
  parameter SI.Frequency fp2=2.0e6 "Pole frequency";
  parameter SI.Frequency fp3=20.0e6 "Pole frequency";
  parameter SI.Frequency fp4=100.0e6 "Pole frequency";
  parameter SI.Frequency fz=5.0e6 "Zero frequency";
  parameter SI.VoltageSlope sr_p=0.5e6 "Slew rate for increase";
  parameter SI.VoltageSlope sr_m=0.5e6 "Slew rate for decrease";
  parameter SI.Resistance Rout=75.0 "Output resistance";
  parameter SI.Current Imaxso=25.0e-3
    "Maximal output current (source current)";
  parameter SI.Current Imaxsi=25.0e-3 "Maximal output current (sink current)";

  // number of intervals: 2500, stop time: 0.003
  parameter SI.Time Ts=0.0000012 "Sampling time";

  // power supply
  final parameter SI.Voltage vcp_abs=abs(vcp)
    "Positive correction value for limiting by p_supply";
  final parameter SI.Voltage vcm_abs=abs(vcm)
    "Positive correction value for limiting by msupply";

  // input stage
  //  Ib = 0.5*(I1 + I2);
  //  Ios = I1 - I2;
  final parameter SI.Current I1=Ib + Ios/2.0 "Current of internal source I1";
  final parameter SI.Current I2=Ib - Ios/2.0 "Current of internal source I2";

  // gain stage (difference and common mode)
  final parameter Real Avd0_val=10.0^(Avd0/20.0) "Differential mode gain";
  final parameter Real Avcm_val=(Avd0_val/(10.0^(CMRR/20.0)))/2.0
    "Common mode gain";

  // slew rate stage
  final parameter SI.VoltageSlope sr_p_val=abs(sr_p)
    "Value of slew rate for increase";
  final parameter SI.VoltageSlope sr_m_val=-abs(sr_m)
    "Negative value of slew rate for increase";

  // output stage
  final parameter SI.Current Imaxso_val=abs(Imaxso) "Orientation out outp";
  final parameter SI.Current Imaxsi_val=abs(Imaxsi) "Orientation into outp";

  Modelica.Electrical.Analog.Interfaces.PositivePin p
    "Positive pin of the input port" annotation (Placement(transformation(
          extent={{-110,-70},{-90,-50}}), iconTransformation(extent={{-110,-70},{-90,-50}})));
  Modelica.Electrical.Analog.Interfaces.NegativePin m
    "Negative pin of the input port" annotation (Placement(transformation(
          extent={{-90,50},{-110,70}}), iconTransformation(extent={{-90,50},{-110,70}})));
  Modelica.Electrical.Analog.Interfaces.PositivePin outp "Output pin"
    annotation (Placement(transformation(extent={{110,-10},{90,10}}), iconTransformation(extent={{110,-10},{90,10}})));
  Modelica.Electrical.Analog.Interfaces.PositivePin p_supply
    "Positive output voltage limitation" annotation (Placement(transformation(
          extent={{-10,90},{10,110}}), iconTransformation(extent={{-10,90},{10,110}})));
  Modelica.Electrical.Analog.Interfaces.NegativePin m_supply
    "Negative output voltage limitation" annotation (Placement(transformation(
          extent={{-10,-110},{10,-90}}), iconTransformation(extent={{-10,-110},{10,-90}})));

  // power supply
  SI.Voltage v_pos;
  SI.Voltage v_neg;

  // input stage
  SI.Voltage v_vos;
  SI.Voltage v_3;
  SI.Voltage v_in;
  SI.Voltage v_4;

  SI.Current i_vos;
  SI.Current i_3;
  SI.Current i_r2;
  SI.Current i_c3;
  SI.Current i_4;

  // frequency response
  Real q_fr1;
  Real q_fr2;
  Real q_fr3;

  // gain stage
  SI.Voltage q_sum;
  SI.Voltage q_sum_help;
  SI.Voltage q_fp1;

  // slew rate stage
  SI.Voltage v_source;

  SI.Voltage x "Auxiliary variable for slew rate";

  // output stage
  SI.Voltage v_out;

  SI.Current i_out;

  // functions
  function FCNiout_limit "Internal limitation function"
    extends Modelica.Icons.Function;
    input SI.Voltage v_source;
    input SI.Voltage v_out;
    input SI.Resistance Rout;
    input SI.Current Imaxsi_val;
    input SI.Current Imaxso_val;
    output SI.Current result;

  algorithm
    if v_out > v_source + Rout*Imaxsi_val then
      result := Imaxsi_val;
    elseif v_out < v_source - Rout*Imaxso_val then
      result := -Imaxso_val;
    else
      result := (v_out - v_source)/Rout;
    end if;
    return;
    annotation (Documentation(info="<html>
<p>Internal limitation function, designed for OpAmpDetailed, not for purpose of external usage.</p>
</html>"));
  end FCNiout_limit;

  function FCNq_sum_limit "Internal limitation function"
    extends Modelica.Icons.Function;
    input SI.Voltage q_sum;
    input SI.Voltage q_sum_ltf;
    input SI.Voltage v_pos;
    input SI.Voltage v_neg;
    input SI.Voltage vcp;
    input SI.Voltage vcm;
    output SI.Voltage result;

  algorithm
    if q_sum > v_pos - vcp and q_sum_ltf >= v_pos - vcp then
      result := v_pos - vcp;
    elseif q_sum < v_neg + vcm and q_sum_ltf <= v_neg + vcm then
      result := v_neg + vcm;
    else
      result := q_sum;
    end if;
    return;
    annotation (Documentation(info="<html>
<p>Internal limitation function, designed for OpAmpDetailed, not for purpose of external usage.</p>
</html>"));
  end FCNq_sum_limit;

initial equation
  v_source = q_fp1;
  x = 0;
equation
  assert(Rout > 0.0, "Rout must be > 0.0.");

  // power supply
  v_pos = p_supply.v;
  v_neg = m_supply.v;

  // input stage
  p.i = i_vos;
  m.i = i_4 - i_r2 - i_c3;
  0 = i_3 + i_r2 + i_c3 - i_vos;
  p.v - m.v = v_vos + v_in;
  v_4 = m.v;
  v_3 = p.v - v_vos;
  v_vos = Vos;
  i_3 = I1 + v_3/Rcm;
  v_in = Rdm*i_r2;
  i_c3 = Cin*der(v_in);
  i_4 = I2 + v_4/Rcm;

  // frequency response
  // Laplace transformation
  der(q_fr1) = 2.0*pi*fp2*(v_in - q_fr1);
  q_fr2 + (1.0/(2.0*pi*fp3))*der(q_fr2) = q_fr1 + (1.0/(2.0*pi*fz))*der(q_fr1);
  der(q_fr3) = 2.0*pi*fp4*(q_fr2 - q_fr3);

  // gain stage
  // Laplace transformation
  q_sum = Avd0_val*q_fr3 + Avcm_val*(v_3 + v_4);
  q_sum_help = FCNq_sum_limit(
      q_sum,
      q_fp1,
      v_pos,
      v_neg,
      vcp_abs,
      vcm_abs);
  der(q_fp1) = 2.0*pi*fp1*(q_sum_help - q_fp1);

  // slew rate stage
  der(x) = (q_fp1 - v_source)/Ts;
  der(v_source) = smooth(0, noEvent(if der(x) > sr_p_val then sr_p_val else
    if der(x) < sr_m_val then sr_m_val else der(x)));

  // output stage
  v_out = outp.v;
  i_out = outp.i;
  i_out = FCNiout_limit(
      v_source,
      v_out,
      Rout,
      Imaxsi_val,
      Imaxso_val);

  p_supply.i = 0;
  m_supply.i = 0;

  annotation (defaultComponentName="opAmp",
    Documentation(info="<html>
<p>The OpAmpDetailed model is a general operational amplifier model. The emphasis is on separating each important data sheet parameter into a sub-circuit independent of the other parameters. The model is broken down into five functional stages <strong>input</strong>, <strong>frequency response</strong>, <strong>gain</strong>, <strong>slew rate</strong> and an <strong>output</strong> stage. Each stage contains data sheet parameters to be modeled. This partitioning and the modelling of the separate submodels are based on the description in [<a href=\"modelica://Modelica.Electrical.Analog.UsersGuide.References\">Conelly1992</a>].</p>
<p>Using [<a href=\"modelica://Modelica.Electrical.Analog.UsersGuide.References\">Conelly1992</a>] Joachim Haase (Fraunhofer Institute for Integrated Circuits, Design Automation Division) transferred 2001 operational amplifier models into VHDL-AMS. Now one of these models, the model &quot;amp(macro)&quot; was transferred into Modelica.</p>
</html>",    revisions="<html>
<dl>
<dt><em>June 17, 2009</em></dt>
<dd>by Susann Wolf initially implemented</dd>
</dl>
</html>"),
    Icon(coordinateSystem(preserveAspectRatio=true, extent={{-100,-100},{100,
            100}}), graphics={
        Text(
          extent={{-150,150},{150,110}},
          textString="%name",
          textColor={0,0,255}),
        Polygon(
          points={{70,0},{-70,80},{-70,-80},{70,0}},
          fillColor={255,255,255},
          fillPattern=FillPattern.Solid,
          lineColor={0,0,255}),
        Line(points={{0,40},{0,110}}, color={0,0,255}),
        Line(points={{0,-40},{0,-90}}, color={0,0,255}),
        Line(points={{-90,60},{-70,60}}, color={0,0,255}),
        Line(points={{-90,-60},{-70,-60}}, color={0,0,255}),
        Line(points={{70,0},{90,0}}, color={0,0,255}),
        Line(points={{-58,50},{-38,50}}, color={0,0,255}),
        Line(points={{-60,-51},{-38,-51}}, color={0,0,255}),
        Line(points={{-49,-40},{-49,-61}}, color={0,0,255})}));
end OpAmpDetailed;

