            -40},{-10,-20}})));

  Modelica.Electrical.Analog.Basic.Resistor Rdistr(R=Rload) annotation (
      Placement(transformation(
        extent={{-10,-10},{10,10}},
        rotation=-90,
        origin={12,-30})));
