within Modelica.Electrical.Batteries.Utilities;
model CCCVcharger
  "Charger with constant current - constant voltage characteristic"
  extends Modelica.Electrical.Analog.Interfaces.OnePort;
  parameter SI.Current I "Constant charge current";
  parameter SI.Time startTime=0 "Start time of charging";
  parameter SI.Time rampTime=60 "Ramp up charging current";
  parameter SI.Voltage Vend "End of charge voltage";
  Boolean CV(start=false, fixed=true) "Indicates CV charging";
equation
  CV=v>=Vend;
  if CV then
    v=Vend;
  else
    i = -I*(if time<startTime then 0 else min(1,(time - startTime)/rampTime));
  end if;
  annotation (defaultComponentName="cccvCharger",
    Icon(graphics={   Rectangle(
        extent={{-100,-100},{100,100}},
        lineColor={0,0,127},
        fillColor={255,255,255},
        fillPattern=FillPattern.Solid), Text(
        extent={{-150,150},{150,110}},
        textString="%name",
        textColor={0,0,255}),
        Polygon(
          points={{20,80},{-50,-20},{0,-20},{-20,-80},{50,20},{0,20},{20,80}},
          lineColor={0,0,255},
          fillColor={0,0,255},
          fillPattern=FillPattern.Solid)}),
    Documentation(info="<html>
<p>
Ideal charger switching from constant current to constant voltage characteristic.
</p>
</html>"));
end CCCVcharger;

within Modelica.Electrical.Batteries.Utilities;
block PulseSeries "Series of pulses"
  import Modelica.Math.BooleanVectors.oneTrue;
  parameter Real amplitude1= 1 "Amplitude of 1st pulse series";
  parameter Integer n1(min=0)=1 "Number of pulses of 1st series";
  parameter SI.Time T1 "Length of pulses of 1st series";
  parameter SI.Time Tp1 "Pause between pulses of 1st series";
  parameter Real amplitude2=-amplitude1 "Amplitude of 2nd pulse series";
  parameter Integer n2(min=0)=1 "Number of pulses of 2nd series";
  parameter SI.Time T2=T1 "Length of pulses of 2nd series";
  parameter SI.Time Tp2=Tp1 "Pause between pulses of 2nd series";
  parameter SI.Time Tp "Pause (in addition to TP1) between the two series"
    annotation(Dialog(groupImage=
      "modelica://Modelica/Resources/Images/Electrical/Batteries/Utilities/PulseSeries.png"));
  extends Modelica.Blocks.Interfaces.SignalSource;
protected
  parameter SI.Time Tstart1[n1]={startTime + (k-1)*(T1 + Tp1) for k in 1:n1};
  parameter SI.Time Tstart2[n2]={startTime + n1*(T1 + Tp1) + Tp + (k-1)*(T2 + Tp2) for k in 1:n2};
  Boolean on1, on2;
equation
  on1 = oneTrue({time >= Tstart1[k] and time < Tstart1[k] + T1 for k in 1:n1});
  on2 = oneTrue({time >= Tstart2[k] and time < Tstart2[k] + T2 for k in 1:n2});
  y= offset + (if on1 then amplitude1 elseif on2 then amplitude2 else 0);
  annotation (Icon(graphics={
        Line(
          points={{-100,0},{-80,0}},
          color={0,0,0},
          pattern=LinePattern.Dash),
        Line(points={{-10,0},{-10,-60},{10,-60},{10,0},{20,0}}, color={0,0,0}),
        Line(points={{-50,0},{-50,60},{-40,60},{-40,0},{-20,0}}, color={0,0,0}),
        Line(
          points={{-20,0},{-10,0}},
          color={0,0,0},
          pattern=LinePattern.Dash),
        Line(points={{-80,0},{-80,60},{-70,60},{-70,0},{-50,0}}, color={0,0,0}),
        Line(points={{20,0},{20,-60},{40,-60},{40,0},{50,0}}, color={0,0,0}),
        Line(points={{50,0},{50,-60},{70,-60},{70,0},{80,0}}, color={0,0,0}),
        Line(
          points={{80,0},{100,0}},
          color={0,0,0},
          pattern=LinePattern.Dash)}), Documentation(info= "<html>
<p>
Starting at <code>time = startTime</code>, first a series of <code>n1</code> pulses of <code>amplitude1</code> with length <code>T1</code> and pause after each pulse <code>Tp1</code> is issued.</p>
<p>
Then, after the pause duration&nbsp;<code>Tp1 + Tp</code>, a series of <code>n2</code> pulses of <code>amplitude2</code> with length <code>T2</code> and pause after each pulse <code>Tp2</code> is issued.
</p>

<p>
<img src=\"modelica://Modelica/Resources/Images/Electrical/Batteries/Utilities/PulseSeries.png\" alt=\"PulseSeries.png\">
</p>
</html>"));
end PulseSeries;

