  connect(powerSensor3.power, add.u1) annotation (Line(points={{20,-29},{20,-20},
          {6,-20},{6,-58}}, color={0,0,127}));
  annotation (Icon(coordinateSystem(preserveAspectRatio=false, extent={{-100,
