      Placement(transformation(
        origin={60,30},
        extent={{-10,-10},{10,10}},
        rotation=90)));
  QuasiStatic.SinglePhase.Basic.Capacitor capacitor(C=C) annotation (Placement(
        transformation(
        origin={30,32},
        extent={{-10,-10},{10,10}},
        rotation=270)));
  QuasiStatic.SinglePhase.Basic.Inductor inductor(L=L) annotation (Placement(
