model AronSensor "Three-phase Aron sensor for active power"
  extends Modelica.Icons.RoundSensor;
  final parameter Integer m(final min=1) = 3 "Number of phases" annotation(Evaluate=true);
  Modelica.Electrical.QuasiStatic.Polyphase.Interfaces.PositivePlug plug_p(final m=m)
    annotation (Placement(transformation(extent={{-110,-10},{-90,10}})));
  Modelica.Electrical.QuasiStatic.Polyphase.Interfaces.NegativePlug plug_n(final m=m)
    annotation (Placement(transformation(extent={{90,-10},{110,10}})));
  Modelica.Blocks.Interfaces.RealOutput activePower(unit="W") "Active power" annotation (Placement(transformation(
        origin={0,-110},
        extent={{10,-10},{-10,10}},
        rotation=90)));
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.PlugToPins_p plugToPins_p(final m=m)
    annotation (Placement(transformation(extent={{-80,-10},{-60,10}})));
  Modelica.Electrical.QuasiStatic.Polyphase.Basic.PlugToPins_n plugToPins_n(final m=m)
    annotation (Placement(transformation(extent={{80,-10},{60,10}})));
  Modelica.Electrical.QuasiStatic.SinglePhase.Sensors.PowerSensor powerSensor1
    annotation (Placement(transformation(extent={{-40,30},{-20,50}})));
  Modelica.Electrical.QuasiStatic.SinglePhase.Sensors.PowerSensor powerSensor3
    annotation (Placement(transformation(extent={{20,-30},{40,-50}})));
  Modelica.Blocks.Math.Add add annotation (Placement(transformation(
        extent={{-10,-10},{10,10}},
        rotation=270,
        origin={0,-70})));
  Modelica.ComplexBlocks.ComplexMath.ComplexToReal complexToReal1(final
      useConjugateInput=false) annotation (Placement(transformation(
        extent={{-10,-10},{10,10}},
        rotation=270,
        origin={-40,-20})));
  Modelica.ComplexBlocks.ComplexMath.ComplexToReal complexToReal3(final
      useConjugateInput=false) annotation (Placement(transformation(
        extent={{-10,-10},{10,10}},
        rotation=270,
        origin={0,-22})));
equation
  connect(add.y, activePower) annotation (Line(points={{0,-81},{0,-110}}, color={0,0,127}));
  connect(plug_p, plugToPins_p.plug_p)
    annotation (Line(points={{-100,0},{-72,0}}, color={85,170,255}));
  connect(plugToPins_n.plug_n, plug_n)
    annotation (Line(points={{72,0},{100,0}}, color={85,170,255}));
  connect(plugToPins_p.pin_p[1], powerSensor1.currentP) annotation (Line(
        points={{-68,0},{-68,40},{-40,40}}, color={85,170,255}));
  connect(powerSensor1.currentP, powerSensor1.voltageP) annotation (Line(
        points={{-40,40},{-40,50},{-30,50}}, color={85,170,255}));
  connect(powerSensor1.currentN, plugToPins_n.pin_n[1]) annotation (Line(
        points={{-20,40},{68,40},{68,0}}, color={85,170,255}));
  connect(plugToPins_p.pin_p[2], plugToPins_n.pin_n[2])
    annotation (Line(points={{-68,0},{68,0}}, color={85,170,255}));
  connect(plugToPins_p.pin_p[3], powerSensor3.currentP) annotation (Line(
        points={{-68,0},{-68,-40},{20,-40}}, color={85,170,255}));
  connect(powerSensor3.currentP, powerSensor3.voltageP) annotation (Line(
        points={{20,-40},{20,-50},{30,-50}}, color={85,170,255}));
  connect(powerSensor3.currentN, plugToPins_n.pin_n[3]) annotation (Line(
        points={{40,-40},{68,-40},{68,0}}, color={85,170,255}));
  connect(complexToReal3.re, add.u1)
    annotation (Line(points={{6,-34},{6,-58}}, color={0,0,127}));
  connect(complexToReal1.re, add.u2) annotation (Line(points={{-34,-32},{
          -34,-50},{-6,-50},{-6,-58}}, color={0,0,127}));
  connect(powerSensor3.apparentPower, complexToReal3.u) annotation (Line(points={{20,-29},{20,10},{0,10},{0,-10}}, color={85,170,255}));
  connect(powerSensor1.apparentPower, complexToReal1.u) annotation (Line(points={{-40,29},{-40,-8}}, color={85,170,255}));
  connect(plugToPins_p.pin_p[2], powerSensor1.voltageN) annotation (Line(
        points={{-68,0},{-30,0},{-30,30}}, color={85,170,255}));
  connect(plugToPins_p.pin_p[2], powerSensor3.voltageN) annotation (Line(
        points={{-68,0},{30,0},{30,-30}}, color={85,170,255}));
  annotation (Icon(coordinateSystem(preserveAspectRatio=false, extent={{-100,
            -100},{100,100}}), graphics={
                                       Line(points={{0,-100},
          {0,-70}}, color={0,0,127}),
        Text(
          extent={{150,-100},{-150,-70}},
          textString="m=%m"),
        Text(
          extent={{-150,80},{150,120}},
          textString="%name",
          textColor={0,0,255}),
        Text(
          extent={{-30,-10},{30,-70}},
          textColor={64,64,64},
          textString="W"),
        Line(points={{-100,0},{100,0}}, color={85,170,255})}),
                                  Documentation(info="<html>
<p>Contains two <a href=\"modelica://Modelica.Electrical.QuasiStatic.SinglePhase.Sensors.PowerSensor\">power meters</a> to measure total active power in a three-phase system.</p>
<p>This device works only in three-phase systems without neutral.</p>
<p>The rationale behind this sensor is that power exchanged between two parts of a circuit is the sum of the products of currents in the <em>m</em> wires connecting the two parts times wires&apos; potentials evaluated with reference to an arbitrary potential <em>v</em><sub>ref</sub>:</p>
<p><em>P</em>=(<em>v</em><sub>1</sub>-<em>v</em><sub>ref</sub>)*<em>i</em><sub>1</sub>+(<em>v</em><sub>2</sub>-<em>v</em><sub>ref</sub>)*<em>i</em><sub>2</sub>+&hellip;+(<em>v</em><sub>m</sub>-<em>v</em><sub>ref</sub>)*<em>i</em><sub>m</sub></p>
<p>In case of a three-phase system without neutral we may want to measure power flowing in a line, connecting, say, the left part of the circuit to its right part. The wires connecting the two parts are only three (i.e., <em>m</em>=3)
and therefore all currents between these two parts are <em>i</em><sub>1</sub>, <em>i</em><sub>2</sub>, <em>i</em><sub>3</sub>.&nbsp;</p>
<p>Since the voltage to be taken as reference is arbitrary, we can take the voltage of conductor 2. Therefore our power becomes:</p>
<p><em>P</em>=(<em>v</em><sub>1</sub>-<em>v</em><sub>2</sub>)*<em>i</em><sub>1</sub>+(<em>v</em><sub>2</sub>-<em>v</em><sub>2</sub>)*<em>i</em><sub>2</sub>+(<em>v</em><sub>3</sub>-<em>v</em><sub>2)</sub>*<em>i</em><sub>3 </sub>=
(<em>v</em><sub>1</sub>-<em>v</em><sub>2</sub>)*i<sub>1</sub>+(<em>v</em><sub>3</sub>-<em>v</em><sub>2</sub>)* i<sub>3</sub></p>
<p>In this way, we can just sum up the power from two wattmeters to get the three-phase power.</p>
<p>Note, that this formula does not work if there are additional current paths between the left and right parts of our circuits, e.g., if both have grounds (and current flows through it).</p>
<p>For more information on why power flowing in a circuit between two subcircuits is the sum of products of voltages times currents, the voltages being measured to an arbitrary reference potential, see
[<a href=\"modelica://Modelica.Electrical.Polyphase.UsersGuide.References\">Ceraolo2014</a>, par. 3.8.1].</p>
</html>"));
end AronSensor;

within Modelica.Electrical.QuasiStatic.Polyphase.Sensors;
model MultiSensor "Polyphase sensor to measure current, voltage and power"
  extends Modelica.Icons.RoundSensor;
  import Modelica.ComplexMath.conj;
  import Modelica.ComplexMath.abs;
  import Modelica.ComplexMath.arg;
  parameter Integer m(min=1) = 3 "Number of phases" annotation(Evaluate=true);
  QuasiStatic.Polyphase.Interfaces.PositivePlug pc(final m=m)
    "Positive plug, current path"
    annotation (Placement(transformation(extent={{-90,-10},{-110,10}})));
  QuasiStatic.Polyphase.Interfaces.NegativePlug nc(final m=m)
    "Negative plug, current path"
    annotation (Placement(transformation(extent={{110,-10},{90,10}})));
  QuasiStatic.Polyphase.Interfaces.PositivePlug pv(final m=m)
    "Positive plug, voltage path"
    annotation (Placement(transformation(extent={{-10,110},{10,90}})));
  QuasiStatic.Polyphase.Interfaces.NegativePlug nv(final m=m)
    "Negative plug, voltage path"
    annotation (Placement(transformation(extent={{10,-110},{-10,-90}})));
  Modelica.ComplexBlocks.Interfaces.ComplexOutput i[m](
    redeclare each final SI.Current re, redeclare each final SI.Current im)
    "Current as complex output signal" annotation (Placement(transformation(
        origin={-60,-110},
        extent={{10,10},{-10,-10}},
        rotation=90)));
  Modelica.ComplexBlocks.Interfaces.ComplexOutput v[m](
    redeclare each final SI.Voltage re, redeclare each final SI.Voltage im)
    "Voltage as complex output signal" annotation (Placement(transformation(
        origin={60,-110},
        extent={{10,10},{-10,-10}},
        rotation=90)));
  Modelica.ComplexBlocks.Interfaces.ComplexOutput apparentPower[m](
    redeclare each final SI.ActivePower re, redeclare each final SI.ReactivePower im)
    "Instantaneous apparent power as complex output signal" annotation (Placement(transformation(
        origin={-110,-60},
        extent={{-10,10},{10,-10}},
        rotation=180)));
  Modelica.ComplexBlocks.Interfaces.ComplexOutput apparentPowerTotal(
    redeclare final SI.ActivePower re, redeclare final SI.ReactivePower im)
    "Sum of instantaneous apparent power as complex output signal" annotation (Placement(transformation(
        origin={110,-60},
        extent={{10,10},{-10,-10}},
        rotation=180)));
  output SI.Current abs_i[m]=abs(i) "Absolute of complex currents";
  output SI.Angle arg_i[m]=arg(i) "Argument of complex currents";
  output SI.Voltage abs_v[m]=abs(v) "Absolute of complex voltages";
  output SI.Angle arg_v[m]=arg(v) "Argument of complex voltages";
  output SI.ApparentPower abs_apparentPower[m]=abs(apparentPower) "Absolute of complex apparent power signals";
  output SI.Angle arg_apparentPower[m]=arg(apparentPower) "Argument of complex apparent power signals";
  output SI.ApparentPower abs_apparentPowerTotal=abs(apparentPowerTotal) "Absolute of sum complex apparent power";
  output SI.Angle arg_apparentPowerTotal=arg(apparentPowerTotal) "Argument of sum complex apparent power";
equation
  Connections.branch(pc.reference, nc.reference);
  pc.reference.gamma = nc.reference.gamma;
  Connections.branch(pv.reference, nv.reference);
  pv.reference.gamma = nv.reference.gamma;
  Connections.branch(pc.reference, pv.reference);
  pc.reference.gamma = pv.reference.gamma;
  pc.pin.i + nc.pin.i = fill(Complex(0), m);
  pc.pin.v - nc.pin.v = fill(Complex(0), m);
  pv.pin.i = fill(Complex(0), m);
  nv.pin.i = fill(Complex(0), m);
  i = pc.pin.i;
  v = pv.pin.v - nv.pin.v;
  apparentPower = v.*conj(i);
  apparentPowerTotal = Complex(sum(apparentPower.re),sum(apparentPower.im));
  annotation (
    Icon(coordinateSystem(preserveAspectRatio=true, extent={{-100,-100},{100,100}}), graphics={
      Line(points = {{0,100},{0,70}}, color={85,170,255}),
      Line(points = {{0,-70},{0,-100}}, color={85,170,255}),
      Line(points = {{-100,0},{100,0}}, color={85,170,255}),
      Line(points = {{0,70},{0,40}}),
        Line(points={{-100,-60},{-80,-60},{-56,-42}},
                                                   color={85,170,255}),
        Line(points={{-60,-100},{-60,-80},{-42,-56}},
                                                   color={85,170,255}),
        Line(points={{60,-100},{60,-80},{42,-56}},
                                                color={85,170,255}),
        Text(
          extent={{-100,-20},{-60,-60}},
            textColor={64,64,64},
            textString="V.A"),
        Text(
          extent={{-80,-60},{-40,-100}},
            textString="A",
            textColor={64,64,64}),
        Text(
          extent={{40,-60},{80,-100}},
            textString="V",
            textColor={64,64,64}),
        Line(points={{100,-60},{80,-60},{56,-42}}, color={85,170,255}),
        Text(
          extent={{-150,110},{150,150}},
          textString="%name",
          textColor={0,0,255})}),
    Documentation(info="<html>
<p>This multi sensor measures currents, voltages and instantaneous electrical power of a polyphase system and has separated voltage and current paths.
The plugs of the voltage paths are pv and nv, the plugs of the current paths are pc and nc.
The internal resistance of each current path is zero, the internal resistance of each voltage path is infinite.</p>

<h4>See also</h4>

<p>
<a href=\"modelica://Modelica.Electrical.QuasiStatic.SinglePhase.Sensors.MultiSensor\">SinglePhase.Sensors.MultiSensor</a>
<a href=\"modelica://Modelica.Electrical.QuasiStatic.Polyphase.Sensors.ReferenceSensor\">ReferenceSensor</a>,
<a href=\"modelica://Modelica.Electrical.QuasiStatic.Polyphase.Sensors.FrequencySensor\">FrequencySensor</a>,
<a href=\"modelica://Modelica.Electrical.QuasiStatic.Polyphase.Sensors.PotentialSensor\">PotentialSensor</a>,
<a href=\"modelica://Modelica.Electrical.QuasiStatic.Polyphase.Sensors.VoltageSensor\">VoltageSensor</a>,
<a href=\"modelica://Modelica.Electrical.QuasiStatic.Polyphase.Sensors.VoltageQuasiRMSSensor\">VoltageQuasiRMSSensor</a>,
<a href=\"modelica://Modelica.Electrical.QuasiStatic.Polyphase.Sensors.CurrentSensor\">CurrentSensor</a>,
<a href=\"modelica://Modelica.Electrical.QuasiStatic.Polyphase.Sensors.CurrentQuasiRMSSensor\">CurrentQuasiRMSSensor</a>,
<a href=\"modelica://Modelica.Electrical.QuasiStatic.Polyphase.Sensors.PowerSensor\">PowerSensor</a>
</p>
</html>",        revisions="<html>
<ul>
<li><em>20170306</em> first implementation by Anton Haumer</li>
</ul>
</html>"));
end MultiSensor;

