          lineColor={192,192,192},
          fillColor={192,192,192},
          fillPattern=FillPattern.Solid),
        Line(points={{-50,100},{-20,100},{-20,70}}, color={85,170,255}),
        Line(points={{50,100},{20,100},{20,70}}, color={85,170,255}),
        Text(
          extent={{-150,-120},{150,-160}},
          textColor={0,0,255},
          textString="%name"),
        Line(
          visible=not useSupport,
          points={{80,-100},{120,-100}}),
