            30}})));
  inner World world(g=0, driveTrainMechanics3D=true) annotation (Placement(
        transformation(extent={{-80,10},{-60,30}})));
  Forces.Torque torque annotation (Placement(transformation(extent={{50,30},{70,50}})));
