    wireframe=false,
    color=color,
    specularCoefficient=specularCoefficient,
    transparency=0,
    R=frame_a.R,
    r_0=frame_a.r_0) if world.enableAnimation and animation annotation (Placement(transformation(extent={{-50,-10},{-30,10}})));

equation
